{
  "schemaVersion": "0.2",
  "slug": "navbar",
  "name": "Navbar",
  "family": "B",
  "status": "experimental",
  "purpose": "Provides horizontal (or stacked, when narrow) primary navigation with an optional brand region.",
  "scenarios": [
    "Site-wide links across the top of a marketing page",
    "Switch application sections from a header",
    "Stack navigation on a compact embedded host"
  ],
  "props": {
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the navigation landmark."
    },
    "items": {
      "type": "node",
      "required": true,
      "description": "Navigation items with value, label, and optional href."
    },
    "brand": {
      "type": "node",
      "required": false,
      "description": "Optional brand or product name region."
    },
    "activeValue": {
      "type": "string",
      "required": false,
      "description": "Value of the current page item."
    },
    "onSelect": {
      "type": "event",
      "required": false,
      "description": "Called with the item value when a control is activated."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "No item marked current."
    },
    {
      "name": "active",
      "description": "An item is marked as the current page."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "header",
      "page"
    ],
    "allowedChildren": [
      "link",
      "button",
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not put the only navigation in a navbar that disappears on compact without an alternative.",
    "Do not use a navbar for sequential wizard progress; use Steps.",
    "Do not use Navbar as AppShell three-end chrome; root tabs are Navigation, stack chrome is NavigationTitle."
  ],
  "a11y": {
    "role": "navigation",
    "keyboard": [
      "Tab moves through brand and items",
      "Enter activates the focused link or button"
    ],
    "focus": "Items are real links or buttons in document order with a visible focus ring.",
    "labeling": "The nav landmark has an accessible name; current page uses aria-current.",
    "wcag": [
      "1.3.1",
      "2.4.1",
      "2.4.7"
    ]
  },
  "responsive": {
    "strategy": "Root is a query container. Compact stacks items; tablet/desktop switch the list to a row. No viewport size media.",
    "breakpoints": {
      "compact": "Brand above a vertical item list; 44px targets.",
      "medium": "Horizontal item list at 48rem container width.",
      "large": "Wider brand padding and item gap at 80rem container width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Row direction follows document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "navbar",
    "states": [
      "default",
      "active"
    ],
    "intents": [
      "navigate-sections"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface NavbarItem {
  value: string
  label: ReactNode
  href?: string
}

export interface NavbarProps {
  label: string
  items: NavbarItem[]
  brand?: ReactNode
  activeValue?: string
  onSelect?: (value: string) => void
  className?: string
}

export function Navbar({
  label,
  items,
  brand,
  activeValue,
  onSelect,
  className,
}: NavbarProps) {
  const classes = ['cu-navbar', className].filter(Boolean).join(' ')

  return (
    <nav
      className={classes}
      aria-label={label}
      data-ai-role="navbar"
      data-ai-intent="navigate-sections"
      data-ai-state={activeValue ? 'active' : 'default'}
    >
      <div className="cu-navbar__frame">
        {brand ? <div className="cu-navbar__brand">{brand}</div> : null}
        <ul className="cu-navbar__list">
          {items.map((item) => {
            const current = activeValue === item.value
            const itemClass = 'cu-navbar__item'
            const labelNode = <span className="cu-navbar__label">{item.label}</span>
            return (
              <li key={item.value} className="cu-navbar__entry">
                {item.href ? (
                  <a
                    className={itemClass}
                    href={item.href}
                    aria-current={current ? 'page' : undefined}
                    onClick={() => onSelect?.(item.value)}
                  >
                    {labelNode}
                  </a>
                ) : (
                  <button
                    type="button"
                    className={itemClass}
                    aria-current={current ? 'page' : undefined}
                    onClick={() => onSelect?.(item.value)}
                  >
                    {labelNode}
                  </button>
                )}
              </li>
            )
          })}
        </ul>
      </div>
    </nav>
  )
}

/*
 * Query container: the nav is the container; the frame consumes it so the
 * stack -> row morph follows the navbar's own inline size rather than the
 * viewport. 48rem == breakpoint.tablet, 80rem == breakpoint.desktop
 * (packages/tokens/src/core/breakpoint.json).
 */
.cu-navbar {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-block-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(
    --cu-color-background-translucent,
    var(--cu-color-background-default)
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  color: var(--cu-color-fg-default);
  container-type: inline-size;
}

.cu-navbar__frame {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
}

.cu-navbar__brand {
  font-weight: 700;
  padding-inline: var(--cu-space-2);
}

.cu-navbar__list {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-1);
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-navbar__item {
  display: flex;
  align-items: center;
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: none;
  border-radius: var(--cu-radius-md);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
}

.cu-navbar__item[aria-current='page'] {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

.cu-navbar__item:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

@media (hover: hover) {
  .cu-navbar__item:hover:not([aria-current='page']) {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

@container (min-width: 48rem) {
  .cu-navbar__frame {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .cu-navbar__list {
    flex-direction: row;
    flex-wrap: wrap;
  }
}

@container (min-width: 80rem) {
  .cu-navbar__list {
    gap: var(--cu-space-2);
  }

  .cu-navbar__brand {
    padding-inline: var(--cu-space-3);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-navbar__item {
    transition-duration: 0.01ms;
  }
}
